/**
 * nanshann 深层响应式状态对象，不属于 TC39 提案 API。
 * createState(data) 返回保持原有 TS 类型的代理；通过属性读写、delete 和数组方法使用。
 * 复用 Signal 的 Computed / batch / 订阅调度，不再提供路径 get/set/subscribe。
 *
 * 普通对象、无原型对象和普通数组按访问需要代理并缓存；其他对象作为原子值。
 * 原始数据不复制：相同对象共用代理，别名/循环引用保留；写入必须经过代理。
 * 属性值、in、自有属性存在性、键遍历分别收集依赖，且只在响应式读取时建节点。
 * 子字段变化不改变父代理身份；父对象替换后，计算会自动切换到新分支的依赖。
 * 不支持访问器、只读/不可配置数据字段、修改描述符/原型或冻结代理。
 * 数组 length 是唯一允许的不可配置自有字段。Map/Set/Date 等内部变化不追踪。
 * 计算期间写入先报错再修改数据；数组复合操作内部 batch，异常不回滚已完成写入。
 * 画布路径属于绑定描述，由后续绑定层逐段读取代理，不依赖状态容器的路径 API。
 */
import { State, assertWritable, batch, isTracking, untrack } from './signal.js';

type Data = Record<PropertyKey, unknown> | unknown[];
type Kind = 'value' | 'has' | 'own';
interface Dependencies {
  value?: Map<PropertyKey, State<number>>;
  has?: Map<PropertyKey, State<number>>;
  own?: Map<PropertyKey, State<number>>;
  keys?: State<number>;
}

const proxies = new WeakMap<object, Data>();
const originals = new WeakMap<object, Data>();
const dependencies = new WeakMap<object, Dependencies>();

function isData(value: unknown): value is Data {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return Array.isArray(value) ? prototype === Array.prototype
    : prototype === Object.prototype || prototype === null;
}

function raw<T>(value: T): T {
  return (value !== null && typeof value === 'object' ? originals.get(value) ?? value : value) as T;
}

function deps(target: Data): Dependencies {
  let result = dependencies.get(target);
  if (!result) {
    result = {};
    dependencies.set(target, result);
  }
  return result;
}

function track(target: Data, key: PropertyKey, kind: Kind): void {
  if (!isTracking()) return;
  const nodes = deps(target)[kind] ??= new Map();
  let signal = nodes.get(key);
  if (!signal) { signal = new State(0); nodes.set(key, signal); }
  signal.get();
}

function touch(signal?: State<number>): void {
  if (signal) signal.set(signal.peek() + 1);
}

function snapshot(target: Data, key: PropertyKey) {
  return { value: raw(Reflect.get(target, key)), own: Object.hasOwn(target, key), has: Reflect.has(target, key) };
}

function notify(target: Data, key: PropertyKey, before: ReturnType<typeof snapshot>, structural = true): void {
  const nodes = dependencies.get(target);
  if (!nodes) return;
  const after = snapshot(target, key);
  if (!Object.is(before.value, after.value)) touch(nodes.value?.get(key));
  if (before.has !== after.has) touch(nodes.has?.get(key));
  if (before.own !== after.own) {
    touch(nodes.own?.get(key));
    if (structural) touch(nodes.keys);
  }
}

function isIndex(key: PropertyKey): key is string {
  return typeof key === 'string' && /^(0|[1-9]\d*)$/.test(key) && Number(key) < 0xFFFFFFFF;
}

// 方法不绑定具体实例，保留 arr.push.call(other, ...) 的原生调用方式。
// 复合写入合并通知，内部读取不成为调用方的响应式依赖。
const mutators = new Map<unknown, (...args: unknown[]) => unknown>();
for (const name of ['push', 'pop', 'shift', 'unshift', 'splice', 'sort', 'reverse', 'copyWithin', 'fill'] as const) {
  const method = Array.prototype[name];
  mutators.set(method, function (this: unknown, ...args: unknown[]) {
    assertWritable();
    return batch(() => untrack(() => Reflect.apply(method, this, args)));
  });
}
// 数组读取返回代理；查找时兼容调用方持有的原对象引用，依赖仍由第一次读取收集。
const searches = new Map<unknown, (...args: unknown[]) => unknown>();
for (const name of ['includes', 'indexOf', 'lastIndexOf'] as const) {
  const method = Array.prototype[name];
  searches.set(method, function (this: unknown, ...args: unknown[]) {
    const result: unknown = Reflect.apply(method, this, args);
    return result === false || result === -1
      ? Reflect.apply(method, raw(this), args.map(raw)) : result;
  });
}

const handler: ProxyHandler<Data> = {
  get(target, key, receiver) {
    track(target, key, 'value');
    const value: unknown = Reflect.get(target, key, receiver);
    if (Array.isArray(target) && mutators.has(value)) return mutators.get(value);
    if (Array.isArray(target) && searches.has(value)) return searches.get(value);
    return Object.hasOwn(target, key) ? wrap(value) : value;
  },

  set(target, key, value) {
    assertWritable();
    return batch(() => untrack(() => {
      const next = raw(value);
      const before = snapshot(target, key);
      if (before.own && Object.is(before.value, next)) return true;
      const oldLength = Array.isArray(target) ? target.length : undefined;
      const nodes = dependencies.get(target);
      // length 截断不会逐个进入 deleteProperty；仅检查已被读取的索引。
      let removed: Map<PropertyKey, ReturnType<typeof snapshot>> | undefined;
      if (oldLength !== undefined && key === 'length' && nodes) {
        removed = new Map();
        for (const map of [nodes.value, nodes.has, nodes.own]) {
          for (const index of map?.keys() ?? []) {
            if (isIndex(index) && !removed.has(index) && Object.hasOwn(target, index)) {
              removed.set(index, snapshot(target, index));
            }
          }
        }
      }
      const keyCount = oldLength !== undefined && key === 'length' && nodes?.keys
        ? Reflect.ownKeys(target).length : undefined;
      // 新属性直接定义为数据字段，不调用原型上的 __proto__ 等 setter。
      const success = before.own ? Reflect.set(target, key, next, target)
        : Reflect.defineProperty(target, key, { value: next, writable: true, enumerable: true, configurable: true });
      if (!success) return false;
      notify(target, key, before);
      if (Array.isArray(target) && oldLength !== target.length) {
        if (key !== 'length') touch(nodes?.value?.get('length'));
        for (const [index, previous] of removed ?? []) notify(target, index, previous, false);
        if (keyCount !== undefined && keyCount !== Reflect.ownKeys(target).length) touch(nodes?.keys);
      }
      return true;
    }));
  },

  deleteProperty(target, key) {
    assertWritable();
    return batch(() => untrack(() => {
      const before = snapshot(target, key);
      const success = Reflect.deleteProperty(target, key);
      if (success) notify(target, key, before);
      return success;
    }));
  },

  has(target, key) { track(target, key, 'has'); return Reflect.has(target, key); },
  ownKeys(target) {
    if (isTracking()) (deps(target).keys ??= new State(0)).get();
    return Reflect.ownKeys(target);
  },
  getOwnPropertyDescriptor(target, key) {
    track(target, key, 'own');
    return Reflect.getOwnPropertyDescriptor(target, key);
  },
  defineProperty() { throw new TypeError('State property descriptors cannot be changed; use assignment'); },
  setPrototypeOf() { throw new TypeError('State prototype cannot be changed'); },
  preventExtensions() { throw new TypeError('State must remain extensible'); },
};

function wrap<T>(value: T): T {
  const target = raw(value);
  if (target === null || typeof target !== 'object') return value;
  const cached = proxies.get(target);
  if (cached) return cached as T;
  if (!isData(target)) return value;
  if (!Object.isExtensible(target)) throw new TypeError('State requires extensible data objects');
  for (const key of Reflect.ownKeys(target)) {
    const descriptor = Reflect.getOwnPropertyDescriptor(target, key)!;
    const length = Array.isArray(target) && key === 'length';
    if (!('value' in descriptor) || !descriptor.writable || (!descriptor.configurable && !length)) {
      throw new TypeError('State requires mutable data properties, without accessors');
    }
  }
  const proxy = new Proxy(target, handler);
  proxies.set(target, proxy);
  originals.set(proxy, target);
  return proxy as T;
}

/** 创建深层响应式普通对象或数组；不复制输入，不增加 get/set 等保留方法名。 */
export function createState<T extends object>(initialValue: T): T {
  if (!isData(raw(initialValue))) throw new TypeError('createState requires a plain object or array');
  return wrap(initialValue);
}
